source='''def transform(grid):
    rows = len(grid)
    width = len(grid[0])
    left_width = width // 2
    left = [row[:left_width] for row in grid]

    # Horizontal rows made entirely of the frame color separate the panels.
    separators = [r for r, row in enumerate(left)
                  if row and row[0] != 0 and all(v == row[0] for v in row)]
    frame_color = left[separators[0]][0]

    def normalized(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    # Collect colored shapes on the right. Each color denotes one shape.
    shapes = {}
    for r in range(rows):
        for c in range(left_width, width):
            color = grid[r][c]
            if color != 0:
                shapes.setdefault(color, set()).add((r, c - left_width))
    shape_masks = {color: normalized(cells) for color, cells in shapes.items()}

    out = [row[:] for row in left]
    for top, bottom in zip(separators, separators[1:]):
        holes = {(r, c) for r in range(top + 1, bottom)
                 for c in range(left_width) if left[r][c] == 0}
        if not holes:
            continue
        mask = normalized(holes)
        match = next((color for color, shape in shape_masks.items()
                      if shape == mask), None)
        if match is None:
            raise ValueError("No colored shape matches a frame opening")
        for r, c in holes:
            out[r][c] = match
    return out
